MERGE INTO target AS t USING source AS s ON t.id = s.id WHEN MATCHED THEN UPDATE SET value = s.value WHEN NOT MATCHED THEN INSERT (id, value) VALUES (s.id, s.value) RETURNING t.id;

WITH merged AS (MERGE INTO target USING source ON target.id = source.id WHEN MATCHED AND source.deleted THEN DELETE WHEN NOT MATCHED BY SOURCE THEN DO NOTHING WHEN NOT MATCHED BY TARGET THEN INSERT DEFAULT VALUES RETURNING target.id) SELECT * FROM merged;

MERGE INTO a_very_long_schema_name.a_very_long_target_table_name AS an_extremely_long_target_alias USING a_very_long_schema_name.a_very_long_source_table_name AS an_extremely_long_source_alias ON an_extremely_long_target_alias.organization_identifier = an_extremely_long_source_alias.organization_identifier WHEN MATCHED AND an_extremely_long_source_alias.should_update_the_existing_record THEN UPDATE SET extremely_long_descriptive_column_name = an_extremely_long_source_alias.extremely_long_descriptive_column_name WHEN NOT MATCHED BY TARGET THEN INSERT (organization_identifier, extremely_long_descriptive_column_name) OVERRIDING SYSTEM VALUE VALUES (an_extremely_long_source_alias.organization_identifier, an_extremely_long_source_alias.extremely_long_descriptive_column_name) RETURNING an_extremely_long_target_alias.organization_identifier;

